interface Type { readonly flags: number; }
const absent = ABSENT;
function getTypeArguments(type: Type): readonly Type[] { return absent ? [type] : [type, type, type]; }
const type: Type = { flags: 7 };
const [yieldType, returnType, nextType] = getTypeArguments(type);
const value: Type = returnType;
console.log(value === undefined ? "undefined" : `${value.flags}`);
